1353	          yield SCaseExpr(SExprInfo(sp, p, Some(d)), param, cmp, eq, in, ncs, ne.headOption)
1354	      case STry(SExprInfo(sp, p, _), body, catchC, forbid, None) =>
1355	        for (nb <- block(body);
1356	             nc <- catchC match {
1357	               case None => Some(None)
1358	               case Some(SCatch(i, name, cs)) =>
1359	                 each(cs, (c: CatchClause) => c match {
1360	                   case SCatchClause(ci, t, b) => block(b).map(SCatchClause(ci, t, _)) })
